<div class="page-actions"><p class="muted">Catálogo de especialidades médicas.</p><?php if(\App\Core\Auth::role()==='admin'):?><a class="btn btn-primary" href="<?= url('/specialties/create') ?>">+ Nueva especialidad</a><?php endif;?></div>
